 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()

    # Each outlined object is a 4-connected component of its frame color.
    for sr in range(h):
        for sc in range(w):
            color = grid[sr][sc]
            if color == background or (sr, sc) in seen:
                continue
            q = deque([(sr, sc)])
            seen.add((sr, sc))
            component = set()
            while q:
                r, c = q.popleft()
                component.add((r, c))
                for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc))
                        q.append((nr,nc))

            r0 = min(r for r, c in component)
            r1 = max(r for r, c in component)
            c0 = min(c for r, c in component)
            c1 = max(c for r, c in component)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = {(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
                         if r in (r0,r1) or c in (c0,c1)}
            if component != perimeter:
                continue
            interior = [(r,c) for r in range(r0+1,r1) for c in range(c0+1,c1)]
            if not interior or any(grid[r][c] != background for r,c in interior):
                continue
            # Odd-sided outlined objects are marked with 7, even-sided with 2.
            fill = 7 if (r1-r0+1) % 2 else 2
            for r,c in interior:
                out[r][c] = fill
    return out

